(36, 'woopay-beta-merchantrecruitment-short-update-09MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(37, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(38, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(39, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(40, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(41, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(42, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(43, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(44, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(45, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(46, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(47, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(48, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(49, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(50, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(51, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(52, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(53, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(54, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(55, 'woo-dotcom-course-2026-06-09', 'marketing', 'en_US', 'Learn how to build your store with WooCommerce', 'In this free course, we\'ll help you set up and run your online store with clear, practical guidance.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(56, 'mollie_incentive_h2_2026_sweden', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Sell more with Swish, Klarna, and Europe’s other most popular options, using Mollie’s smooth and reliable checkout experience. Sign up today and process up to SEK 50,000 with 0% fees until December 31. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-09-11 06:46:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(57, 'wc-admin-customizing-product-catalog', 'info', 'en_US', 'نحوۀ سفارشی‌سازی فهرست محصول', 'شما می خواهید کاتالوگ محصولات و تصاویر شما عالی به نظر برسند و با نام تجاری شما هماهنگ باشند. این راهنما تمام نکاتی را که برای به نمایش گذاشتن محصولاتتان در فروشگاهتان نیاز دارید به شما ارائه می دهد.', '{}', 'unactioned', 'woocommerce-admin', '2026-09-17 18:27:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(58, 'wc-admin-launch-checklist', 'info', 'en_US', 'آماده اجرای فروشگاه هستید؟', 'برای اطمینان از اینکه هرگز آن احساس غرق شدن \"چه فراموش کردم\" را ندارید، چک لیست ضروری قبل از راه اندازی را گردآوری کرده ایم.', '{}', 'unactioned', 'woocommerce-admin', '2026-09-17 18:27:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(59, 'wc-admin-onboarding-payments-reminder', 'info', 'en_US', 'شروع به پذیرش پرداخت‌ها در فروشگاه خود کنید!', 'برای پرداخت با درگاه های مختلف آغاز کنید. از میان بیش از 100 درگاه پرداخت برای ووکامرس می‌توانید انتخاب کنید.', '{}', 'unactioned', 'woocommerce-admin', '2026-09-17 18:27:54', NULL, 0, 'plain', '', 0, 0, 'info'),
(60, 'wc-admin-usage-tracking-opt-in', 'info', 'en_US', 'برای بهبود ووکامرس با استفاده از رهگیری استفاده کمک کنید', 'جمع آوری داده های استفاده به ما امکان می دهد ووکامرس را بهبود دهیم. هنگامی که ویژگی‌های جدید را ارزیابی می‌کنیم، کیفیت بروز رسانی را قضاوت می‌کنیم یا تشخیص می‌دهیم که آیا بهبود منطقی است، فروشگاه شما در نظر گرفته می‌شود. همیشه می‌توانید از <a href=\"http://localhost:8080/wp-anishop/wp-admin/admin.php?page=wc-settings&amp;tab=advanced&amp;section=woocommerce_com\" target=\"_blank\">تنظیمات</a> بازدید کرده و توقف اشتراک‌گذاری داده‌ها را انتخاب کنید. <a href=\"https://woocommerce.com/usage-tracking?utm_medium=product\" target=\"_blank\">اطلاعات بیشتر</a> درباره داده‌هایی که جمع‌آوری می‌کنیم.', '{}', 'unactioned', 'woocommerce-admin', '2026-09-17 18:27:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(61, 'wc-admin-woocommerce-payments', 'marketing', 'en_US', 'روش جدید پرداخت را امتحان کنید', 'کارت‌های اعتباری و نقدی را در سایت خود به طور ایمن بپذیرید. معاملات را بدون ترک پیشخوان وردپرس خود مدیریت کنید. فقط با <strong>WooPayments</strong>.<br><br>با کلیک روی «شروع کنید»، <a href=\"https://wordpress.com/tos/\" target=\"_blank\">شرایط خدمات</a> ما را می‌پذیرید', '{}', 'unactioned', 'woocommerce-admin', '2026-09-17 18:27:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(62, 'google-for-woocommerce-mapi-update', 'update', 'en_US', 'Action Required by October 12, 2026: Your products will stop showing on Google', 'You need to update Google for WooCommerce to the latest version (3.9.4) to continue syncing your products to Google Merchant Center without issues. The Google for WooCommerce version you have installed uses the legacy Content API which has been deprecated and replaced by the advanced <a href=\"https://support.google.com/merchants/answer/16494522?hl=en\">Google Merchant API</a>.', '{}', 'pending', 'woocommerce.com', '2026-11-06 11:59:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(63, 'wcpay_security_update_2026_11', 'update', 'en_US', 'Security update for WooPayments', 'Please update to the latest version of WooPayments now to address a security issue. If the update does not appear or fails, follow the update guidance or contact WooCommerce Support with your installed version.', '{}', 'pending', 'woocommerce.com', '2026-11-06 11:59:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(64, 'mollie_incentive_h2_2026_IT', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Mollie’s smooth and reliable checkout experience can boost conversions with Satispay, BANCOMAT Pay, and Europe’s other most popular payment methods. Sign up today and process up to €50,000 with 0% fees your first 30 days. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-11-06 11:59:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(65, 'mollie_incentive_h2_2026_all_geos', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Mollie\'s checkout can boost conversions with iDEAL, Bancontact, Klarna, and other popular European payment methods. Sign up today and process up to €50,000 with 0% fees in your first 30 days. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-11-06 11:59:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(66, 'woopayments_bfcm_2026', 'marketing', 'en_US', 'A quick tweak to grow Black Friday sales', 'Over Black Friday weekend last year, 20% of orders used express checkouts and 15% paid in installments. Maximize your earnings and make sure Apple Pay, Google Pay, and buy now, pay later options are enabled in WooPayments. \r\n\r\n<a href=\"https://woocommerce.com/bfcm-payments/\">Learn more</a>.', '{}', 'pending', 'woocommerce.com', '2026-11-07 12:16:07', NULL, 0, 'plain', '', 0, 0, 'info');

